import java.util.*;

class Solution {
    public int minToll(int[] toll) {
        int n = toll.length;
        if (n == 1) return Math.min(0, toll[0]) == 0 ? 0 : toll[0];
        int a = toll[0], b = toll[1];          // cheapest cost to stand on rung i-2, i-1
        for (int i = 2; i < n; i++) {
            int c = toll[i] + Math.min(a, b);
            a = b;
            b = c;
        }
        return Math.min(a, b);                  // step off the top from either rung
    }
}

